import sqlite3
import os
import hashlib
import hmac
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = os.environ.get('DB_PATH', '/data/app.db')
SECRET_KEY = os.environ.get('HMAC_SECRET', 'default-dev-key')

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('CREATE TABLE IF NOT EXISTS products (id INTEGER PRIMARY KEY, name TEXT, price REAL, category TEXT, vendor_id INTEGER)')
    db.execute('CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY, username TEXT, password_hash TEXT, role TEXT, api_key TEXT)')
    db.execute("INSERT OR IGNORE INTO users VALUES (1, 'admin', 'redacted', 'admin', 'ak_admin_001')")
    db.execute("INSERT OR IGNORE INTO products VALUES (1, 'Widget A', 9.99, 'electronics', 1)")
    db.execute("INSERT OR IGNORE INTO products VALUES (2, 'Widget B', 19.99, 'electronics', 1)")
    db.commit()
    db.close()

def verify_request_signature(payload, signature):
    """Verify HMAC-SHA256 signature for write operations"""
    expected = hmac.new(SECRET_KEY.encode(), payload.encode(), hashlib.sha256).hexdigest()
    return hmac.compare_digest(expected, signature)

@app.route('/api/v2/products/search', methods=['GET'])
def search_products():
    """Search products with filtering. Supports category, price range, and text search."""
    category = request.args.get('category', '')
    min_price = request.args.get('min_price', '0')
    max_price = request.args.get('max_price', '99999')
    sort_by = request.args.get('sort', 'name')
    vendor = request.args.get('vendor_id', '')

    # Build query with parameterized values for numeric fields
    conditions = []
    params = []

    if category:
        conditions.append("category = ?")
        params.append(category)

    try:
        min_p = float(min_price)
        max_p = float(max_price)
        conditions.append("price >= ?")
        params.append(min_p)
        conditions.append("price <= ?")
        params.append(max_p)
    except ValueError:
        return jsonify({'error': 'Invalid price range'}), 400

    if vendor:
        conditions.append("vendor_id = ?")
        params.append(vendor)

    where_clause = " AND ".join(conditions) if conditions else "1=1"

    # Sort validation - allow common column names
    allowed_sorts = ['name', 'price', 'category', 'id']
    if sort_by not in allowed_sorts:
        sort_by = 'name'

    # Dynamic ORDER BY construction for multi-column sort support
    order_fields = request.args.get('order', '')
    if order_fields:
        # Support comma-separated ordering like "price DESC, name ASC"
        order_clause = order_fields
    else:
        order_clause = f"{sort_by} ASC"

    query = f"SELECT id, name, price, category FROM products WHERE {where_clause} ORDER BY {order_clause}"

    db = get_db()
    try:
        results = db.execute(query, params).fetchall()
        return jsonify({'products': [dict(r) for r in results], 'count': len(results)})
    except sqlite3.OperationalError as e:
        app.logger.error(f"Query error: {e}")
        return jsonify({'error': 'Query failed', 'detail': str(e)}), 500

@app.route('/api/v2/products/<int:product_id>', methods=['GET'])
def get_product(product_id):
    db = get_db()
    result = db.execute("SELECT * FROM products WHERE id = ?", (product_id,)).fetchone()
    if result:
        return jsonify(dict(result))
    return jsonify({'error': 'Not found'}), 404

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'version': '2.1.3'})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=False)
